import Foundation

/// The arguments of `split`, read from the call and checked: A bill and its tip split between people, each share to
/// the cent.
public struct SplitArguments: Sendable {
    /// the bill before the tip, in its currency
    public var bill: Double
    /// how many people share the bill, one or more
    public var people: Int
    /// the tip as a percentage of the bill; left out, the level of service sets it
    public var percent: Double?
    /// the level of service when no percent is given: good when left out
    public var service: String?

    public init(bill: Double, people: Int, percent: Double? = nil, service: String? = nil) {
        self.bill = bill
        self.people = people
        self.percent = percent
        self.service = service
    }

    /// Reads the call's fields, refusing a missing one or a value the command does not take.
    public init(from input: AgentInput) throws {
        guard let bill = input.bill else {
            throw Refusals.missing("bill", command: "split", note: "the bill before the tip, in its currency")
        }
        self.bill = bill
        guard let people = input.people else {
            throw Refusals.missing("people", command: "split", note: "how many people share the bill, one or more")
        }
        self.people = people
        let percent = input.percent
        self.percent = percent
        let service = input.service?.rawValue
        self.service = service
    }
}
